import { cn } from '@cascivo/core/pure'
import { builtin, t } from '@cascivo/i18n'
import { HoverCard, HoverCardContent, HoverCardTrigger } from '../hover-card/hover-card'
import { sourceHref } from '../sources/sources'
import type { AiSource } from '../sources/sources'
import { VisuallyHidden } from '../visually-hidden/visually-hidden'
import styles from './inline-citation.module.css'

export interface InlineCitationProps {
  index: number
  source: AiSource
  labels?: {
    source?: string
  }
  className?: string
}

export function InlineCitation({ index, source, labels, className }: InlineCitationProps) {
  const href = sourceHref(source.url)
  // The name starts with the visible number (WCAG 2.5.3) and carries the title, so the
  // citation makes sense without the hover card.
  const prefix =
    labels?.source?.replace('{index}', String(index)) ?? t(builtin.inlineCitation.source, { index })
  const name = `${prefix}: ${source.title}`

  const label = (
    <>
      <span aria-hidden="true">{index}</span>
      <VisuallyHidden>{name}</VisuallyHidden>
    </>
  )

  return (
    <sup className={cn(styles['citation'], className)}>
      <HoverCard>
        <HoverCardTrigger>
          {href ? (
            <a className={styles['marker']} href={href}>
              {label}
            </a>
          ) : (
            // A refused URL keeps the marker and its name, but is no longer a link.
            <span className={styles['marker']}>{label}</span>
          )}
        </HoverCardTrigger>
        <HoverCardContent className={cn(styles['card'])}>
          <span className={styles['title']}>{source.title}</span>
          {href ? <span className={styles['host']}>{new URL(href).hostname}</span> : null}
          {source.description ? (
            <span className={styles['description']}>{source.description}</span>
          ) : null}
        </HoverCardContent>
      </HoverCard>
    </sup>
  )
}

@layer cascivo.component {
  .citation {
    line-height: 0;
  }

  .marker {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-inline-size: 1.25em;
    padding-inline: 0.25em;
    border-radius: var(--cascivo-radius-full);
    background-color: var(--cascivo-color-ai-subtle);
    color: var(--cascivo-color-text);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-xs);
    font-variant-numeric: tabular-nums;
    line-height: 1.5;
    text-decoration: none;

    &:hover {
      background-color: var(--cascivo-color-ai-sheen);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }
  }

  /* This class lands on HoverCard's popover element, so it must not declare a visible
     display at rest: any author display beats the UA rule that hides a closed popover. */
  .card {
    display: none;
    flex-direction: column;
    gap: var(--cascivo-space-1);
    max-inline-size: 20rem;
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-snug);

    &:popover-open {
      display: flex;
    }
  }

  .title {
    font-weight: var(--cascivo-font-medium);
    color: var(--cascivo-color-text);
  }

  .host {
    font-size: var(--cascivo-text-xs);
    color: var(--cascivo-color-text-muted);
  }

  .description {
    color: var(--cascivo-color-text-muted);
  }
}

@media (forced-colors: active) {
  .marker {
    border: 1px solid CanvasText;
  }

  .marker:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
}
